contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test entry; include a dummy uint parameter to range over
    function run(uint dummy) public payable {
        require(true);

        // observe before-values
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        bool reverted;
        // top-level state-changing call on c: owner (this contract) calls withdrawAll()
        // use try/catch but keep the call as its own statement
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule: withdrawAll either reverts and leaves balance and depositsCount unchanged,
        // or succeeds and sets contract balance to zero while depositsCount is unchanged.
        assert(
            (reverted && afterDeposits == beforeDeposits && afterBalance == beforeBalance)
            ||
            (!reverted && afterDeposits == beforeDeposits && afterBalance == 0)
        );
    }

    receive() external payable { }
}

